head.script:
scwin.onpageload = function() {
	dataList1.setJSON([
		{ region:"서울", industry:"제조",   amount:100 },
		{ region:"서울", industry:"서비스", amount:30  },
		{ region:"부산", industry:"제조",   amount:200 },
		{ region:"부산", industry:"서비스", amount:70  }
	]);
};

scwin.downloadObjectForm = function() {
	gridView1.advancedExcelDownload({
		fileName: "WAEA_950_headerFooter.xlsx",
		extension: "xlsx",
		printSet: {
			header: { left: "농협은행", center: "월별 실적 집계", right: "대외비" },
			footer: { center: "출력용 - 재배포 금지" }
		}
	});
};

scwin.downloadStringForm = function() {
	gridView1.advancedExcelDownload({
		fileName: "WAEA_950_headerCenter.xlsx",
		extension: "xlsx",
		printSet: {
			header: "월별 실적 집계"
		}
	});
};

scwin.downloadCombined = function() {
	gridView1.advancedExcelDownload({
		fileName: "WAEA_950_combined.xlsx",
		extension: "xlsx",
		printSet: {
			fitToPage: "true",
			landScape: "true",
			header: { center: "월별 실적 집계" },
			footer: { right: "대외비" }
		}
	});
};

scwin.downloadDefault = function() {
	gridView1.advancedExcelDownload({
		fileName: "WAEA_950_default.xlsx",
		extension: "xlsx"
	});
};
